-- 생성자로 의존성을 넘긴다

public class GreetingService {
    String greet(String name) { return "안녕 " + name; }
}

public class GreetServlet extends HttpServlet {
    private final GreetingService service;

    public GreetServlet(GreetingService service) {
        this.service = service;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        resp.setContentType("text/plain;charset=UTF-8");
        resp.getWriter().write(
                service.greet(req.getParameter("name")));
    }
}

// main 에서
GreetingService service = new GreetingService();
tomcat.addServlet("", "greet", new GreetServlet(service));
context.addServletMappingDecoded("/greet", "greet");

